        long base = *dst;
        *(sk_word_t *)(base + (slot >> 6) * 8) |= 1ULL << (slot & 0x3f);
        sk_word_t *ks = (sk_word_t*)(*(long*)(base + 0x30) + slot*0x10);
        ks[0] = k0; ks[1] = k1;
